package com.cpf.data.persistence.sql;import com.cpf.data.persistence.api.database.CpfDataAccessIntent;/** 명시적인 Read/Write routing override. */public final class CpfDataAccessContext {private static final ThreadLocal<CpfDataAccessIntent> LOCAL=new ThreadLocal<>();private CpfDataAccessContext(){}public static CpfDataAccessIntent current(){return LOCAL.get();}public static Scope open(CpfDataAccessIntent intent){CpfDataAccessIntent prev=LOCAL.get();LOCAL.set(intent);return()->{if(prev==null)LOCAL.remove();else LOCAL.set(prev);};}public interface Scope extends AutoCloseable{@Override void close();}}